import java.lang.*;
import java.util.*;
import java.math.*;


class DifferAtOneBitPos {
    public static Boolean differAtOneBitPos(int a, int b) {
        int diff = a ^ b;
        int count = 0;
        while (diff > 0) {
            diff = diff & (diff - 1);
            count++;
        }
        return count == 1;
    }
}

