import java.math.*;


class EvenBitSetNumber {
    public static int evenBitSetNumber(int n) {
        int nBit = n;
        while (nBit > 0) {
            if ((nBit & 1) == 1) {
                n |= nBit << 1;
            }
            nBit >>= 1;
        }
        return n;
    }
}

