class UniqueProduct {
    public static int uniqueProduct(List<Integer> listData) {
        HashSet<Integer> set = new HashSet<Integer>();
        int prod = 1;
        for (Integer number : listData) {
            if (!set.contains(number)) {
                set.add(number);
                prod *= number;
            }
        }
        return prod;
    }
}

